/**
 * Shape of contracts/models.json — task → provider, model, effort, cache prefix key, batch flag. The only place model IDs live (§8A). Every task named in contracts/providers/llm.ts must appear.
 */
export interface Models {
  schema_version: string;
  updated: string;
  source: string;
  defaults: {
    on_refusal: OnRefusal;
    cache_min_prefix_tokens: number;
    new_thread_seed: {
      ddl: true;
      thread_state: "thread-state.schema.json";
      note?: string;
    };
  };
  tasks: {
    route: Task;
    rewrite: Task;
    idea: Task;
    learn_critique: Task;
    precedent_search: Task;
    promote: Task;
    interpret: Task;
    compile: Task;
    explain: Task;
    profile_draft: Task;
    narrate: Task;
  };
}
/**
 * stop_reason refusal: surface to the user and log (never silently alter), or start a new thread on another model seeded from the DDL (a thread never switches model, §8A.2).
 */
export interface OnRefusal {
  action: "surface" | "new_thread_with";
  model?: string;
  log: true;
}
export interface Task {
  provider: "anthropic" | "openai";
  model: string;
  effort: "low" | "medium" | "high" | "xhigh" | "max" | null;
  effort_note?: string;
  max_tokens: number;
  cache_prefix_key: string;
  batch: boolean;
  tools?: "web_search"[];
  /**
   * Contract schema (file, optionally #/$defs/name) the output must validate against.
   */
  structured_output: string;
  /**
   * Whether the model accepts mid-conversation system messages. false → context changes start a new thread seeded from the DDL (Sonnet 5 and Haiku 4.5 do not support them).
   */
  mid_conversation_system: boolean;
  on_refusal?: OnRefusal;
  provisional?: boolean;
  decision?: number;
  stage?: 1 | 2 | 3;
  eval_candidates?: {
    provider: "anthropic" | "openai";
    model: string | null;
    name?: string;
    role?: "candidate" | "ceiling_reference";
    note?: string;
  }[];
}
